import{_ as e,o as d,c as a,ah as o}from"./chunks/framework.Yx0DUrwu.js";const m=JSON.parse('{"title":"淋巴细胞发育与活化","description":"","frontmatter":{},"headers":[],"relativePath":"biology/lymphocyte-development-activation.md","filePath":"biology/lymphocyte-development-activation.md","lastUpdated":1787828013000}'),c={name:"biology/lymphocyte-development-activation.md"};function l(i,t,n,r,h,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="淋巴细胞发育与活化" tabindex="-1">淋巴细胞发育与活化 <a class="header-anchor" href="#淋巴细胞发育与活化" aria-label="Permalink to &quot;淋巴细胞发育与活化&quot;">​</a></h1><p>适应性免疫的能力来自一个看似矛盾的过程：先通过 V(D)J recombination 制造大量随机受体，再通过发育选择和外周调控清除危险的自身反应性克隆。这个过程决定了 T/B cell repertoire 的广度，也决定了免疫耐受的底线 [1]。</p><h2 id="受体库如何产生" tabindex="-1">受体库如何产生 <a class="header-anchor" href="#受体库如何产生" aria-label="Permalink to &quot;受体库如何产生&quot;">​</a></h2><div class="flow-strip"><span>造血干细胞</span><span>淋巴祖细胞</span><span>V(D)J 重排</span><span>受体表达测试</span><span>阳性选择</span><span>阴性选择</span><span>外周成熟</span><span>抗原激活</span></div><table tabindex="0"><thead><tr><th>机制</th><th>发生对象</th><th>作用</th><th>分析提示</th></tr></thead><tbody><tr><td>V(D)J recombination</td><td>BCR heavy/light chain, TCR alpha/beta/gamma/delta</td><td>产生受体多样性。</td><td>VDJ-seq 可连接 clonotype 与转录状态。</td></tr><tr><td>junctional diversity</td><td>重排连接处核苷酸增减</td><td>主要扩展 CDR3 多样性。</td><td>CDR3 是 clonotype 分析核心区域。</td></tr><tr><td>allelic exclusion</td><td>B cells and T cells</td><td>让单个细胞主要表达一个特异性受体。</td><td>双重受体或 ambient contamination 需要谨慎判断。</td></tr><tr><td>class switch recombination</td><td>activated B cells</td><td>改变 antibody isotype，不改变抗原特异性。</td><td><code>IGHM</code>, <code>IGHD</code>, <code>IGHG</code>, <code>IGHA</code>, <code>AICDA</code>。</td></tr></tbody></table><h2 id="b-cell-发育" tabindex="-1">B cell 发育 <a class="header-anchor" href="#b-cell-发育" aria-label="Permalink to &quot;B cell 发育&quot;">​</a></h2><p>B cell 在骨髓中完成早期发育：重链重排、pre-BCR 检查、轻链重排、自身反应性检查，然后进入外周继续成熟。单细胞中常见状态包括 immature B, naive B, memory B, germinal center B, plasmablast, plasma cell。</p><table tabindex="0"><thead><tr><th>状态</th><th>常见 marker</th><th>功能解释</th></tr></thead><tbody><tr><td>naive B cell</td><td><code>MS4A1</code>, <code>CD79A</code>, <code>CD79B</code>, <code>IGHD</code>, <code>IGHM</code></td><td>未充分经历抗原驱动分化。</td></tr><tr><td>germinal center B</td><td><code>BCL6</code>, <code>AICDA</code>, <code>MKI67</code></td><td>体细胞高频突变、选择和亲和力成熟。</td></tr><tr><td>memory B cell</td><td><code>CD27</code>, switched <code>IGHG</code>/<code>IGHA</code></td><td>再次应答更快，常有类别转换。</td></tr><tr><td>plasma cell</td><td><code>MZB1</code>, <code>XBP1</code>, <code>JCHAIN</code>, <code>SDC1</code></td><td>大量分泌抗体。</td></tr></tbody></table><h2 id="t-cell-发育" tabindex="-1">T cell 发育 <a class="header-anchor" href="#t-cell-发育" aria-label="Permalink to &quot;T cell 发育&quot;">​</a></h2><p>T cell 起源于骨髓，但关键发育发生在胸腺。Notch signaling 推动 T lineage commitment；pre-TCR 检查 beta chain；阳性选择保留能识别 self-MHC 的细胞；阴性选择清除高亲和识别自身抗原的细胞。部分自身反应性细胞会进入 Treg 或 innate-like T cell fate。</p><div class="doc-callout important"><strong>选择不是越强越好</strong><p>TCR 信号太弱，细胞无法通过阳性选择；太强，可能触发阴性选择或 Treg fate。免疫系统是在识别能力和自身耐受之间找平衡。</p></div><h2 id="tcr-bcr-信号和共刺激" tabindex="-1">TCR/BCR 信号和共刺激 <a class="header-anchor" href="#tcr-bcr-信号和共刺激" aria-label="Permalink to &quot;TCR/BCR 信号和共刺激&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>关键分子</th><th>作用</th><th>单细胞解释</th></tr></thead><tbody><tr><td>TCR signal</td><td><code>CD3D/E/G</code>, <code>LCK</code>, <code>ZAP70</code>, <code>LAT</code></td><td>抗原识别后启动胞内级联。</td><td><code>FOS</code>, <code>JUN</code>, <code>NR4A1</code>, <code>IL2RA</code> 可提示近期激活。</td></tr><tr><td>BCR signal</td><td><code>CD79A/B</code>, <code>SYK</code>, <code>BLNK</code></td><td>抗原结合后促进 B cell activation。</td><td>与 antigen uptake、Tfh help、class switching 联合解释。</td></tr><tr><td>costimulation</td><td>CD28, CD40, ICOS</td><td>提供完全激活信号。</td><td>T cell priming、T-B interaction、Tfh response。</td></tr><tr><td>coinhibition</td><td>CTLA-4, PD-1, phosphatase recruitment</td><td>限制过强免疫反应。</td><td>exhaustion、Treg function、checkpoint therapy response。</td></tr></tbody></table><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>为什么 V(D)J recombination 必须配套中枢和外周耐受？</li><li>阳性选择和阴性选择分别筛选什么？</li><li>CD28、CTLA-4 和 PD-1 在免疫调控中有什么差异？</li><li>单细胞 TCR clonotype 扩增一定代表抗原特异性吗？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',17)])])}const b=e(c,[["render",l]]);export{m as __pageData,b as default};
